// ============================================================================
//  Network identity, IP allow-list and automatic blocking
// ============================================================================

function client_ip(): string
{
    $ip = (string) ($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
    if (setting('trust_proxy') === '1' && !empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        // The right-most entry is the one appended by the (trusted) proxy itself.
        $parts = array_map('trim', explode(',', (string) $_SERVER['HTTP_X_FORWARDED_FOR']));
        $last = end($parts);
        if ($last !== false && filter_var($last, FILTER_VALIDATE_IP)) {
            $ip = $last;
        }
    }
    return $ip;
}

function ip_match(string $ip, string $rule): bool
{
    $rule = trim($rule);
    $a = @inet_pton($ip);
    if ($rule === '' || $a === false) {
        return false;
    }
    if (!str_contains($rule, '/')) {
        return @inet_pton($rule) === $a;
    }
    [$net, $bits] = explode('/', $rule, 2);
    $b = @inet_pton($net);
    if ($b === false || strlen($a) !== strlen($b) || !ctype_digit($bits)) {
        return false;
    }
    $bits = min((int) $bits, strlen($a) * 8);
    $bytes = intdiv($bits, 8);
    $rem = $bits % 8;
    if (substr($a, 0, $bytes) !== substr($b, 0, $bytes)) {
        return false;
    }
    if ($rem === 0) {
        return true;
    }
    $mask = (0xFF << (8 - $rem)) & 0xFF;
    return (ord($a[$bytes]) & $mask) === (ord($b[$bytes]) & $mask);
}

function ip_allowed(string $ip, ?string $list = null): bool
{
    $rules = lines($list ?? setting('ip_allowlist'));
    if (!$rules) {
        return true;
    }
    foreach ($rules as $r) {
        if (ip_match($ip, $r)) {
            return true;
        }
    }
    return false;
}

function blocked_until(string $ip): int
{
    $st = db()->prepare('SELECT until FROM blocks WHERE ip = ? AND until > ?');
    $st->execute([$ip, time()]);
    return (int) ($st->fetchColumn() ?: 0);
}

function register_failure(string $ip, string $kind, ?string $username = null): void
{
    $pdo = db();
    $now = time();
    $username = $username !== null ? substr($username, 0, 64) : null;
    $pdo->prepare('INSERT INTO attempts (ip, username, kind, created_at) VALUES (?, ?, ?, ?)')->execute([$ip, $username, $kind, $now]);
    audit('auth.fail', $kind . ($username ? " (user '$username')" : ''), $username ?: '-', $ip);

    // Count failures inside the window, but only those after the last block was issued.
    $st = $pdo->prepare('SELECT created_at FROM blocks WHERE ip = ?');
    $st->execute([$ip]);
    $since = max($now - (int) setting('attempt_window'), (int) ($st->fetchColumn() ?: 0));
    $st = $pdo->prepare('SELECT COUNT(*) FROM attempts WHERE ip = ? AND created_at > ?');
    $st->execute([$ip, $since]);
    $max = max(1, (int) setting('max_attempts'));
    if ((int) $st->fetchColumn() >= $max) {
        block_ip($ip, "Automatic: $max failed attempts", null);
    }
    if (random_int(1, 50) === 1) {
        $pdo->prepare('DELETE FROM attempts WHERE created_at < ?')->execute([$now - 30 * 86400]);
    }
}

function block_ip(string $ip, string $reason, ?int $seconds, ?string $actor = null): int
{
    $pdo = db();
    $now = time();
    $st = $pdo->prepare('SELECT until, strikes FROM blocks WHERE ip = ?');
    $st->execute([$ip]);
    $row = $st->fetch();
    // Repeat offenders get exponentially longer blocks; strikes decay after 30 quiet days.
    $strikes = ($row && (int) $row['until'] > $now - 30 * 86400) ? (int) $row['strikes'] + 1 : 1;
    if ($seconds === null) {
        $seconds = (int) min((int) setting('block_max'), (int) setting('block_seconds') * (2 ** min($strikes - 1, 20)));
    }
    $until = $now + max(60, $seconds);
    $pdo->prepare('INSERT INTO blocks (ip, until, strikes, reason, created_at) VALUES (?, ?, ?, ?, ?)
                   ON CONFLICT(ip) DO UPDATE SET until = excluded.until, strikes = excluded.strikes,
                   reason = excluded.reason, created_at = excluded.created_at')
        ->execute([$ip, $until, $strikes, $reason, $now]);
    audit('security.block', "$ip blocked until " . date('Y-m-d H:i:s', $until) . " (strike $strikes): $reason", $actor ?? 'system', $ip);
    return $until;
}

// ---- src/20-web.php --------------------------------------------------

// ============================================================================
//  Web entry, HTTP auth, sessions, CSRF
// ============================================================================

function web_main(): void
{
    ini_set('display_errors', '0');
    try {
        ensure_storage();
        db();
    } catch (Throwable $e) {
        error_log('DPLY: ' . $e->getMessage());
        http_response_code(500);
        header('Content-Type: text/plain; charset=utf-8');
        echo 'DPLY cannot open its data directory. Check that ' . DPLY_DATA . ' is writable by the PHP user.';
        return;
    }
    send_security_headers();
    if (!setup_done()) {
        http_response_code(503);
        render_bare('Setup required', '<div class="card"><h1>Setup required</h1><p>Initial setup is done on the server '
            . 'command line so nobody can claim this console over the web. Run (as the PHP user):</p>'
            . '<pre>sudo -u ' . h(proc_user()) . ' php ' . h(DPLY_DIR) . '/index.php setup</pre></div>');
        return;
    }
    $ip = client_ip();
    if (!ip_allowed($ip)) {
        http_response_code(403);
        render_bare('Forbidden', '<div class="card"><h1>403 — Forbidden</h1><p>Your address is not allowed.</p></div>');
        return;
    }
    if ($until = blocked_until($ip)) {
        blocked_response($until);
        return;
    }
    http_auth_gate($ip);
    start_session();
    dispatch();
}

function send_security_headers(): void
{
    header('X-Frame-Options: DENY');
    header('X-Content-Type-Options: nosniff');
    header('Referrer-Policy: no-referrer');
    header('Cache-Control: no-store, no-cache, must-revalidate, private');
    header('Pragma: no-cache');
    header('X-Robots-Tag: noindex, nofollow');
    header('Permissions-Policy: camera=(), microphone=(), geolocation=()');
    header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-" . csp_nonce() . "'; "
        . "connect-src 'self'; img-src 'self' data:; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
    if (is_https()) {
        header('Strict-Transport-Security: max-age=31536000');
    }
}

function csp_nonce(): string
{
    static $n = null;
    return $n ??= base64_encode(random_bytes(16));
}

function is_https(): bool
{
    if (!empty($_SERVER['HTTPS']) && strtolower((string) $_SERVER['HTTPS']) !== 'off') {
        return true;
    }
    return setting('trust_proxy') === '1' && strtolower((string) ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '')) === 'https';
}

function blocked_response(int $until): void
{
    http_response_code(403);
    header('Retry-After: ' . max(1, $until - time()));
    render_bare('Blocked', '<div class="card"><h1>Access temporarily blocked</h1><p>Too many failed authentication attempts '
        . 'from your address. Try again after ' . h(date('Y-m-d H:i:s T', $until)) . '.</p></div>');
}

function basic_credentials(): array
{
    if (isset($_SERVER['PHP_AUTH_USER'])) {
        return [(string) $_SERVER['PHP_AUTH_USER'], (string) ($_SERVER['PHP_AUTH_PW'] ?? '')];
    }
    $hdr = (string) ($_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? '');
    if (stripos($hdr, 'basic ') === 0) {
        $dec = base64_decode(substr($hdr, 6), true);
        if ($dec !== false && str_contains($dec, ':')) {
            return explode(':', $dec, 2);
        }
    }
    return [null, null];
}

function http_auth_gate(string $ip): void
{
    [$u, $p] = basic_credentials();
    if ($u !== null) {
        $okUser = hash_equals(setting('http_user'), $u);
        $okPass = password_verify((string) $p, setting('http_pass_hash'));
        if ($okUser && $okPass) {
            return;
        }
        register_failure($ip, 'http', $u);
        if ($until = blocked_until($ip)) {
            blocked_response($until);
            exit;
        }
    }
    header('WWW-Authenticate: Basic realm="DPLY", charset="UTF-8"');
    http_response_code(401);
    render_bare('Authentication required', '<div class="card"><h1>401 — Authentication required</h1></div>');
    exit;
}

function start_session(): void
{
    ini_set('session.use_strict_mode', '1');
    ini_set('session.use_only_cookies', '1');
    ini_set('session.use_trans_sid', '0');
    ini_set('session.gc_maxlifetime', (string) max(3600, (int) setting('session_absolute')));
    session_save_path(DPLY_DATA . '/sessions');
    session_name(is_https() ? '__Host-dply' : 'dply_sid');
    session_set_cookie_params([
        'lifetime' => 0,
        'path'     => is_https() ? '/' : (rtrim(dirname((string) $_SERVER['SCRIPT_NAME']), '/') . '/'),
        'secure'   => is_https(),
        'httponly' => true,
        'samesite' => 'Strict',
    ]);
    session_start();
}

function csrf_token(): string
{
    if (empty($_SESSION['csrf'])) {
        $_SESSION['csrf'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf'];
}

function csrf_field(): string
{
    return '<input type="hidden" name="_csrf" value="' . h(csrf_token()) . '">';
}

function csrf_ok(): bool
{
    $t = (string) ($_POST['_csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '');
    return $t !== '' && !empty($_SESSION['csrf']) && hash_equals($_SESSION['csrf'], $t);
}

function ua_hash(): string
{
    return hash('sha256', (string) ($_SERVER['HTTP_USER_AGENT'] ?? ''));
}

function current_user(): ?array
{
    static $cached = false;
    if ($cached !== false) {
        return $cached;
    }
    if (session_status() !== PHP_SESSION_ACTIVE || empty($_SESSION['uid'])) {
        return null; // not cached: may log in later in this request
    }
    $st = db()->prepare('SELECT * FROM users WHERE id = ?');
    $st->execute([(int) $_SESSION['uid']]);
    $row = $st->fetch();
    $now = time();
    $valid = $row
        && (int) $row['active'] === 1
        && (int) $row['session_version'] === (int) ($_SESSION['sv'] ?? 0)
        && hash_equals((string) ($_SESSION['ua'] ?? ''), ua_hash())
        && $now - (int) ($_SESSION['act'] ?? 0) <= (int) setting('session_idle')
        && $now - (int) ($_SESSION['iat'] ?? 0) <= (int) setting('session_absolute');
    if (!$valid) {
        reset_session();
        flash('warn', 'Your session has ended. Please sign in again.');
        return $cached = null;
    }
    $_SESSION['act'] = $now;
    $row['perm_list'] = array_values(array_filter(explode(',', (string) $row['perms'])));
    return $cached = $row;
}

function reset_session(): void
{
    $flash = $_SESSION['flash'] ?? [];
    $_SESSION = [];
    session_regenerate_id(true);
    $_SESSION['flash'] = $flash;
}

function can(string $perm): bool
{
    $u = current_user();
    if (!$u) {
        return false;
    }
    $p = $u['perm_list'];
    if (in_array('admin', $p, true)) {
        return true;
    }
    if ($perm === 'terminal') {
        return in_array('terminal', $p, true) || in_array('terminal_full', $p, true);
    }
    return in_array($perm, $p, true);
}

function sudo_fresh(): bool
{
    return time() - (int) ($_SESSION['sudo'] ?? 0) <= (int) setting('sudo_ttl');
}

function flash(string $type, string $msg, ?string $pre = null): void
{
    $_SESSION['flash'][] = [$type, $msg, $pre];
}

function redirect(string $to): never
{
    header('Location: ' . $to, true, 303);
    exit;
}

function json_out(array $data, int $code = 200): never
{
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data, JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

function safe_return(string $r): string
{
    return preg_match('/^\?a=[a-z_]+(&[A-Za-z0-9_]+=[A-Za-z0-9_.%\-]*)*$/', $r) ? $r : '?a=dashboard';
}

function dispatch(): void
{
    $a = (string) ($_GET['a'] ?? 'dashboard');
    if (!preg_match('/^[a-z_]{1,32}$/', $a)) {
        $a = 'dashboard';
    }
    $post = ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST';
    if ($post && !csrf_ok()) {
        if ($a === 'term_exec') {
            json_out(['error' => 'Invalid security token — reload the page.'], 400);
        }
        flash('err', 'Your form expired or was invalid. Please try again.');
        redirect(current_user() ? '?a=' . $a : '?a=login');
    }

    $user = current_user();
    if (!$user) {
        if ($a === 'login') {
            $post ? do_login() : page_login();
        } elseif ($a === 'login_2fa') {
            $post ? do_login_2fa() : page_login_2fa();
        } elseif ($a === 'term_exec') {
            json_out(['error' => 'Session expired — reload and sign in.'], 401);
        } else {
            redirect('?a=login');
        }
        return;
    }

    // action => [required permission, needs fresh password confirmation]
    $routes = [
        'dashboard'  => [null, false],
        'deploy'     => ['deploy', false],
        'deploy_log' => ['deploy', false],
        'artisan'    => ['artisan', false],
        'terminal'   => ['terminal', true],
        'term_exec'  => ['terminal', true],
        'env'        => ['env', true],
        'keys'       => ['keys', true],
        'users'      => ['admin', true],
        'security'   => ['admin', true],
        'settings'   => ['admin', true],
        'audit'      => ['admin', false],
        'profile'    => [null, false],
        'reauth'     => [null, false],
        'logout'     => [null, false],
        'login'      => [null, false],
    ];
    if ($a === 'login' || $a === 'login_2fa') {
        redirect('?a=dashboard');
    }
    if (!isset($routes[$a])) {
        http_response_code(404);
        render('Not found', '<div class="card"><h1>404 — Not found</h1></div>');
        return;
    }
    [$perm, $sudo] = $routes[$a];
    if ($perm !== null && !can($perm)) {
        audit('access.denied', "action=$a");
        if ($a === 'term_exec') {
            json_out(['error' => 'Permission denied.'], 403);
        }
        http_response_code(403);
        render('Forbidden', '<div class="card"><h1>403 — Permission denied</h1><p>Your account lacks the <code>'
            . h($perm) . '</code> permission.</p></div>');
        return;
    }
    if ($sudo && !sudo_fresh()) {
        if ($a === 'term_exec') {
            json_out(['reauth' => true]);
        }
        $ret = $post ? '?a=' . $a : ('?' . (string) ($_SERVER['QUERY_STRING'] ?? 'a=' . $a));
        redirect('?a=reauth&return=' . rawurlencode(safe_return($ret)));
    }
    $fn = ($post ? 'do_' : 'page_') . $a;
    if (!function_exists($fn)) {
        http_response_code(405);
        render('Method not allowed', '<div class="card"><h1>405 — Method not allowed</h1></div>');
        return;
    }
    $fn();
}

// ---- src/25-auth.php -------------------------------------------------

// ============================================================================
//  Login, 2FA, re-auth, logout
// ============================================================================

function page_login(): void
{
    render_bare('Sign in', '<form method="post" action="?a=login" class="card login">' . csrf_field()
        . '<h1>DPLY — sign in</h1>'
        . '<label><span>Username</span><input type="text" name="username" autocomplete="username" required autofocus maxlength="64"></label>'
        . '<label><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label>'
        . '<button class="primary" type="submit">Sign in</button></form>', true);
}

function find_user(string $username): ?array
{
    $st = db()->prepare('SELECT * FROM users WHERE username = ?');
    $st->execute([$username]);
    return $st->fetch() ?: null;
}

function dummy_hash(): string
{
    static $h = null;
    return $h ??= hash_pw(bin2hex(random_bytes(8)));
}

function do_login(): void
{
    $ip = client_ip();
    $username = trim((string) ($_POST['username'] ?? ''));
    $password = (string) ($_POST['password'] ?? '');
    $row = (strlen($username) <= 64 && strlen($password) <= 1024) ? find_user($username) : null;
    $now = time();
    // Always run a hash verification so response timing does not reveal valid usernames.
    $pwOk = password_verify($password, $row['password_hash'] ?? dummy_hash());
    $ok = $row && $pwOk && (int) $row['active'] === 1 && (int) $row['locked_until'] <= $now;
    if (!$ok) {
        register_failure($ip, 'login', $username);
        if ($row && !$pwOk) {
            user_failure($row);
        }
        if ($until = blocked_until($ip)) {
            blocked_response($until);
            exit;
        }
        flash('err', 'Invalid credentials, or the account is disabled / temporarily locked.');
        redirect('?a=login');
    }
    if (password_needs_rehash($row['password_hash'], defined('PASSWORD_ARGON2ID') ? PASSWORD_ARGON2ID : PASSWORD_BCRYPT)) {
        db()->prepare('UPDATE users SET password_hash = ? WHERE id = ?')->execute([hash_pw($password), $row['id']]);
    }
    if (!empty($row['totp_secret'])) {
        session_regenerate_id(true);
        $_SESSION['pending_uid'] = (int) $row['id'];
        $_SESSION['pending_at'] = $now;
        redirect('?a=login_2fa');
    }
    complete_login($row);
}

function user_failure(array $row): void
{
    $count = (int) $row['failed_count'] + 1;
    $max = max(1, (int) setting('max_attempts'));
    if ($count >= $max) {
        $until = time() + (int) setting('block_seconds');
        db()->prepare('UPDATE users SET failed_count = 0, locked_until = ? WHERE id = ?')->execute([$until, $row['id']]);
        audit('user.locked', "User '{$row['username']}' locked until " . date('Y-m-d H:i:s', $until), 'system');
    } else {
        db()->prepare('UPDATE users SET failed_count = ? WHERE id = ?')->execute([$count, $row['id']]);
    }
}

function complete_login(array $row): never
{
    $flash = $_SESSION['flash'] ?? [];
    session_regenerate_id(true);
    $_SESSION = [
        'uid'   => (int) $row['id'],
        'sv'    => (int) $row['session_version'],
        'iat'   => time(),
        'act'   => time(),
        'sudo'  => time(),
        'ua'    => ua_hash(),
        'csrf'  => bin2hex(random_bytes(32)),
        'flash' => $flash,
    ];
    db()->prepare('UPDATE users SET failed_count = 0, locked_until = 0, last_login_at = ?, last_login_ip = ? WHERE id = ?')
        ->execute([time(), client_ip(), $row['id']]);
    audit('auth.login', 'Signed in', $row['username']);
    redirect('?a=dashboard');
}

function page_login_2fa(): void
{
    if (empty($_SESSION['pending_uid'])) {
        redirect('?a=login');
    }
    render_bare('Two-factor', '<form method="post" action="?a=login_2fa" class="card login">' . csrf_field()
        . '<h1>Two-factor code</h1><p class="mute">Enter the 6-digit code from your authenticator app.</p>'
        . '<label><span>Code</span><input type="text" name="code" inputmode="numeric" pattern="[0-9 ]{6,7}" autocomplete="one-time-code" required autofocus></label>'
        . '<button class="primary" type="submit">Verify</button> <a href="?a=login">Cancel</a></form>', true);
}

function do_login_2fa(): void
{
    $uid = (int) ($_SESSION['pending_uid'] ?? 0);
    if (!$uid || time() - (int) ($_SESSION['pending_at'] ?? 0) > 300) {
        unset($_SESSION['pending_uid'], $_SESSION['pending_at']);
        flash('err', 'Two-factor step expired. Sign in again.');
        redirect('?a=login');
    }
    $st = db()->prepare('SELECT * FROM users WHERE id = ?');
    $st->execute([$uid]);
    $row = $st->fetch();
    $code = preg_replace('/\D/', '', (string) ($_POST['code'] ?? ''));
    $step = $row ? totp_verify(dec((string) $row['totp_secret']), $code, (int) $row['totp_last']) : null;
    if (!$row || $step === null || (int) $row['active'] !== 1) {
        register_failure(client_ip(), 'totp', $row['username'] ?? null);
        if ($row) {
            user_failure($row);
        }
        if ($until = blocked_until(client_ip())) {
            blocked_response($until);
            exit;
        }
        flash('err', 'Invalid code.');
        redirect('?a=login_2fa');
    }
    db()->prepare('UPDATE users SET totp_last = ? WHERE id = ?')->execute([$step, $uid]);
    complete_login($row);
}

function page_reauth(): void
{
    $ret = safe_return((string) ($_GET['return'] ?? '?a=dashboard'));
    render('Confirm password', '<form method="post" action="?a=reauth" class="card login">' . csrf_field()
        . '<h1>Confirm your password</h1><p class="mute">This area is sensitive. Re-enter your password to continue '
        . '(valid for ' . (int) ceil((int) setting('sudo_ttl') / 60) . ' minutes).</p>'
        . '<input type="hidden" name="return" value="' . h($ret) . '">'
        . '<label><span>Password</span><input type="password" name="password" autocomplete="current-password" required autofocus></label>'
        . '<button class="primary" type="submit">Confirm</button></form>');
}

function do_reauth(): void
{
    $u = current_user();
    $ret = safe_return((string) ($_POST['return'] ?? ''));
    if (!password_verify((string) ($_POST['password'] ?? ''), $u['password_hash'])) {
        register_failure(client_ip(), 'reauth', $u['username']);
        user_failure($u);
        if ($until = blocked_until(client_ip())) {
            blocked_response($until);
            exit;
        }
        flash('err', 'Wrong password.');
        redirect('?a=reauth&return=' . rawurlencode($ret));
    }
    $_SESSION['sudo'] = time();
    audit('auth.reauth', 'Password re-confirmed');
    redirect($ret);
}

function do_logout(): void
{
    audit('auth.logout', 'Signed out');
    reset_session();
    flash('ok', 'Signed out.');
    redirect('?a=login');
}

// ---- TOTP (RFC 6238) --------------------------------------------------------

function b32_encode(string $bin): string
{
    $alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $bits = '';
    foreach (str_split($bin) as $c) {
        $bits .= str_pad(decbin(ord($c)), 8, '0', STR_PAD_LEFT);
    }
    $out = '';
    foreach (str_split($bits, 5) as $chunk) {
        $out .= $alpha[bindec(str_pad($chunk, 5, '0'))];
    }
    return $out;
}

function b32_decode(string $s): string
{
    $alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $bits = '';
    foreach (str_split(strtoupper(rtrim($s, '='))) as $c) {
        $i = strpos($alpha, $c);
        if ($i === false) {
            return '';
        }
        $bits .= str_pad(decbin($i), 5, '0', STR_PAD_LEFT);
    }
    $out = '';
    foreach (str_split($bits, 8) as $byte) {
        if (strlen($byte) === 8) {
            $out .= chr(bindec($byte));
        }
    }
    return $out;
}

function totp_code(string $secret, int $step): string
{
    $h = hash_hmac('sha1', pack('N2', 0, $step), b32_decode($secret), true);
    $o = ord($h[19]) & 0x0F;
    $n = (unpack('N', substr($h, $o, 4))[1] & 0x7FFFFFFF) % 1000000;
    return str_pad((string) $n, 6, '0', STR_PAD_LEFT);
}

/** Returns the matched time-step (for replay protection) or null. */
function totp_verify(string $secret, string $code, int $lastStep): ?int
{
    if ($secret === '' || strlen($code) !== 6) {
        return null;
    }
    $now = intdiv(time(), 30);
    for ($i = -1; $i <= 1; $i++) {
        $s = $now + $i;
        if ($s > $lastStep && hash_equals(totp_code($secret, $s), $code)) {
            return $s;
        }
    }
    return null;
}

// ---- src/30-process.php ----------------------------------------------

// ============================================================================
//  Process execution helpers
// ============================================================================

function env_path(): string
{
    $p = (string) (getenv('PATH') ?: '');
    $dirs = array_filter(array_merge(explode(':', $p), [PHP_BINDIR, '/usr/local/sbin', '/usr/local/bin', '/usr/sbin', '/usr/bin', '/sbin', '/bin']));
    return implode(':', array_unique($dirs));
}

function find_bin(string $name): ?string
{
    if ($name === '') {
        return null;
    }
    if (str_contains($name, '/')) {
        return is_file($name) && is_executable($name) ? $name : null;
    }
    foreach (explode(':', env_path()) as $d) {
        $f = rtrim($d, '/') . '/' . $name;
        if (is_file($f) && is_executable($f)) {
            return $f;
        }
    }
    return null;
}

function php_bin(): string
{
    $s = trim(setting('php_bin'));
    if ($s !== '') {
        return $s;
    }
    $c = [];
    if (PHP_BINARY !== '' && !preg_match('/fpm|cgi|apache|httpd|litespeed|lsphp|frankenphp/i', basename(PHP_BINARY))) {
        $c[] = PHP_BINARY;
    }
    $c[] = PHP_BINDIR . '/php' . PHP_MAJOR_VERSION . '.' . PHP_MINOR_VERSION;
    $c[] = PHP_BINDIR . '/php';
    foreach ($c as $f) {
        if (is_file($f) && is_executable($f)) {
            return $f;
        }
    }
    return find_bin('php' . PHP_MAJOR_VERSION . '.' . PHP_MINOR_VERSION) ?? find_bin('php') ?? 'php';
}

function git_bin(): string
{
    return find_bin(setting('git_bin') ?: 'git') ?? 'git';
}

function composer_cmd(array $args): array
{
    $c = trim(setting('composer_bin')) ?: 'composer';
    if (str_ends_with($c, '.phar')) {
        return array_merge([php_bin(), $c], $args);
    }
    return array_merge([find_bin($c) ?? $c], $args);
}

function artisan_cmd(array $args): array
{
    return array_merge([php_bin(), 'artisan'], $args, ['--no-interaction', '--no-ansi']);
}

function project_root(): string
{
    return rtrim(setting('project_root'), '/') ?: '/';
}

function known_hosts(): string
{
    return DPLY_DATA . '/keys/known_hosts';
}

function ssh_key_dir(): string
{
    return DPLY_DATA . '/keys/ssh';
}

function active_key_path(): ?string
{
    $k = setting('ssh_key');
    $f = ssh_key_dir() . '/' . $k;
    return ($k !== '' && valid_key_name($k) && is_file($f)) ? $f : null;
}

function ssh_command(?string $key): string
{
    $s = 'ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=' . escapeshellarg(known_hosts());
    if ($key) {
        $s .= ' -o IdentitiesOnly=yes -i ' . escapeshellarg($key);
    }
    return $s;
}

/** Environment for git: token goes in an in-memory config header (never into URLs, argv or .git/config). */
function git_env(): array
{
    $cfg = [['safe.directory', project_root()]];
    $env = [];
    $auth = setting('git_auth');
    if ($auth === 'token' && ($tok = dec(setting('git_token'))) !== '') {
        $cfg[] = ['credential.helper', ''];
        $cfg[] = ['http.extraHeader', 'Authorization: Basic ' . base64_encode((setting('git_token_user') ?: 'x-access-token') . ':' . $tok)];
    }
    $env['GIT_SSH_COMMAND'] = ssh_command($auth === 'ssh' ? active_key_path() : null);
    $env['GIT_CONFIG_COUNT'] = (string) count($cfg);
    foreach ($cfg as $i => [$k, $v]) {
        $env["GIT_CONFIG_KEY_$i"] = $k;
        $env["GIT_CONFIG_VALUE_$i"] = $v;
    }
    return $env;
}

function proc_env(bool $withGit = false): array
{
    $home = DPLY_DATA . '/home';
    $env = [
        'PATH'                    => env_path(),
        'HOME'                    => $home,
        'COMPOSER_HOME'           => $home . '/.composer',
        'COMPOSER_NO_INTERACTION' => '1',
        'LANG'                    => 'C.UTF-8',
        'TERM'                    => 'dumb',
        'GIT_TERMINAL_PROMPT'     => '0',
        'GIT_PAGER'               => 'cat',
        'PAGER'                   => 'cat',
    ];
    return $withGit ? array_merge($env, git_env()) : $env;
}

/**
 * Run a command (argv array = no shell). Returns ['code', 'out' (stdout+stderr), 'stdout', 'timeout'].
 */
function run_proc(array $cmd, string $cwd, array $env, int $timeout = 900, ?callable $onChunk = null): array
{
    $spec = [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
    $p = @proc_open($cmd, $spec, $pipes, is_dir($cwd) ? $cwd : null, $env);
    if (!is_resource($p)) {
        $msg = 'Failed to start process: ' . ($cmd[0] ?? '?') . "\n";
        if ($onChunk) {
            $onChunk($msg);
        }
        return ['code' => 127, 'out' => $msg, 'stdout' => '', 'timeout' => false];
    }
    fclose($pipes[0]);
    stream_set_blocking($pipes[1], false);
    stream_set_blocking($pipes[2], false);
    $out = $stdout = '';
    $start = $lastData = microtime(true);
    $timedOut = false;
    while (true) {
        $r = [];
        foreach ([1, 2] as $i) {
            if (!feof($pipes[$i])) {
                $r[] = $pipes[$i];
            }
        }
        if (!$r) {
            break;
        }
        $w = $e = null;
        if (@stream_select($r, $w, $e, 1) === false) {
            break;
        }
        foreach ($r as $s) {
            $chunk = (string) fread($s, 65536);
            if ($chunk === '') {
                continue;
            }
            $lastData = microtime(true);
            if (strlen($out) < DPLY_MAX_OUTPUT) {
                $out .= $chunk;
            }
            if ($s === $pipes[1] && strlen($stdout) < DPLY_MAX_OUTPUT) {
                $stdout .= $chunk;
            }
            if ($onChunk) {
                $onChunk($chunk);
            }
        }
        if ($onChunk && microtime(true) - $lastData > 15) {
            $onChunk(null); // keep-alive for proxies
            $lastData = microtime(true);
        }
        if (microtime(true) - $start > $timeout) {
            $timedOut = true;
            proc_terminate($p, 9);
            break;
        }
    }
    $st = proc_get_status($p);
    while ($st['running'] && microtime(true) - $start <= $timeout + 5) {
        usleep(50000);
        $st = proc_get_status($p);
    }
    if ($st['running']) {
        proc_terminate($p, 9);
        $timedOut = true;
    }
    fclose($pipes[1]);
    fclose($pipes[2]);
    $code = (int) $st['exitcode'];
    $closed = proc_close($p);
    if ($code === -1) {
        $code = $closed;
    }
    if (strlen($out) >= DPLY_MAX_OUTPUT) {
        $out .= "\n[output truncated]\n";
    }
    return ['code' => $timedOut ? 124 : $code, 'out' => $out, 'stdout' => $stdout, 'timeout' => $timedOut];
}

function git_out(array $args, int $timeout = 30): ?string
{
    if (!is_dir(project_root() . '/.git')) {
        return null;
    }
    $r = run_proc(array_merge([git_bin()], $args), project_root(), proc_env(true), $timeout);
    return $r['code'] === 0 ? rtrim($r['stdout']) : null;
}

function cmd_display(array $cmd): string
{
    $s = implode(' ', array_map(fn($a) => preg_match('#^[A-Za-z0-9_/.:=,@+%-]+$#', (string) $a) ? $a : escapeshellarg((string) $a), $cmd));
    return (string) preg_replace('/(--secret=)\S+/', '$1***', $s);
}

function strip_ansi(string $s): string
{
    return (string) preg_replace('/\e\[[0-9;?]*[ -\/]*[@-~]|\e\][^\a]*\a|\r(?!\n)/', '', $s);
}

function parse_args(string $s): ?array
{
    $args = [];
    $cur = '';
    $has = false;
    $q = null;
    $len = strlen($s);
    for ($i = 0; $i < $len; $i++) {
        $c = $s[$i];
        if ($q === "'") {
            if ($c === "'") {
                $q = null;
            } else {
                $cur .= $c;
            }
        } elseif ($q === '"') {
            if ($c === '\\' && $i + 1 < $len && in_array($s[$i + 1], ['"', '\\'], true)) {
                $cur .= $s[++$i];
            } elseif ($c === '"') {
                $q = null;
            } else {
                $cur .= $c;
            }
        } elseif ($c === "'" || $c === '"') {
            $q = $c;
            $has = true;
        } elseif ($c === '\\' && $i + 1 < $len) {
            $cur .= $s[++$i];
            $has = true;
        } elseif (ctype_space($c)) {
            if ($has || $cur !== '') {
                $args[] = $cur;
            }
            $cur = '';
            $has = false;
        } else {
            $cur .= $c;
        }
    }
    if ($q !== null) {
        return null;
    }
    if ($has || $cur !== '') {
        $args[] = $cur;
    }
    return $args;
}

function lines(string $s): array
{
    return array_values(array_filter(array_map('trim', preg_split('/\R/', $s) ?: []), fn($l) => $l !== '' && $l[0] !== '#'));
}

function path_within(string $path, string $root): bool
{
    $root = rtrim($root, '/');
    return $path === $root || str_starts_with($path, $root . '/');
}

function proc_user(): string
{
    if (function_exists('posix_geteuid') && function_exists('posix_getpwuid')) {
        $p = posix_getpwuid(posix_geteuid());
        return $p['name'] ?? (string) posix_geteuid();
    }
    return get_current_user();
}

function owner_name(string $f): string
{
    $uid = @fileowner($f);
    if ($uid === false) {
        return '?';
    }
    if (function_exists('posix_getpwuid') && ($p = posix_getpwuid($uid))) {
        return $p['name'];
    }
    return (string) $uid;
}

function cmd_timeout(): int
{
    return max(30, (int) setting('cmd_timeout'));
}

function down_args(): array
{
    $a = ['down', '--retry=60'];
    if (($s = setting('maint_secret')) !== '') {
        $a[] = '--secret=' . $s;
    }
    return $a;
}

// ---- src/40-deploy-engine.php ----------------------------------------

// ============================================================================
//  Deployment engine
// ============================================================================

function selected_steps(array $in): array
{
    $in = array_map('strval', $in);
    return array_values(array_filter(array_keys(DPLY_STEPS), fn($k) => in_array($k, $in, true)));
}

function default_steps(): array
{
    return selected_steps(explode(',', setting('post_steps')));
}

function repo_rel_path(string $abs): ?string
{
    $root = project_root();
    $real = realpath($abs) ?: $abs;
    return path_within($real, $root) ? ltrim(substr($real, strlen(rtrim($root, '/'))), '/') : null;
}

/**
 * Fetch + sync the working tree, then run the post-deploy steps.
 * $rollbackTo: commit hash to reset to instead of fetching.
 */
function deploy_run(string $actor, array $steps, ?string $rollbackTo = null, ?callable $echo = null): array
{
    $lock = fopen(DPLY_DATA . '/deploy.lock', 'c');
    if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) {
        return ['ok' => false, 'id' => 0, 'msg' => 'Another deployment is already running.'];
    }
    @set_time_limit(0);
    ignore_user_abort(true);

    $pdo = db();
    $root = project_root();
    $branch = setting('branch');
    $pdo->prepare('INSERT INTO deployments (actor, kind, branch, status, steps, started_at, log) VALUES (?, ?, ?, ?, ?, ?, ?)')
        ->execute([$actor, $rollbackTo ? 'rollback' : 'deploy', $branch, 'running', implode(',', $steps), time(), '']);
    $id = (int) $pdo->lastInsertId();
    audit($rollbackTo ? 'deploy.rollback' : 'deploy.start', "#$id " . ($rollbackTo ? "to $rollbackTo" : "branch $branch"), $actor);

    $log = '';
    $L = function (?string $s) use (&$log, $echo): void {
        if ($s !== null) {
            $log .= $s;
        }
        if ($echo) {
            $echo($s);
        }
    };
    $git = [git_bin()];
    $genv = proc_env(true);
    $exec = function (string $label, array $cmd, bool $fatal = true, bool $withGit = false) use ($L, $root, $genv): bool {
        $L("\n▶ $label\n\$ " . cmd_display($cmd) . "\n");
        $r = run_proc($cmd, $root, $withGit ? $genv : proc_env(), cmd_timeout(), function ($c) use ($L) {
            $L($c === null ? null : strip_ansi($c));
        });
        $L(($r['timeout'] ? "\n[timed out]" : '') . "\n[exit {$r['code']}]\n");
        if ($r['code'] !== 0 && $fatal) {
            throw new RuntimeException("Step failed: $label");
        }
        return $r['code'] === 0;
    };

    $ok = true;
    $before = $after = '';
    $L(sprintf("DPLY %s — %s #%d by %s at %s\nProject: %s\n", DPLY_VERSION, $rollbackTo ? 'rollback' : 'deployment', $id, $actor, date('Y-m-d H:i:s'), $root));
    try {
        if (!is_dir($root)) {
            throw new RuntimeException("Project root not found: $root");
        }
        $url = trim(setting('repo_url'));
        if (!is_dir("$root/.git")) {
            if ($rollbackTo) {
                throw new RuntimeException('Not a git repository — nothing to roll back.');
            }
            if ($url === '') {
                throw new RuntimeException('The project is not a git repository and no repository URL is configured (Settings).');
            }
            $L("\nNo .git directory: initialising a repository in place (existing files are kept).\n");
            $exec('Initialise repository', array_merge($git, ['init', '-q', '-b', $branch]), true, true);
            $exec('Add origin remote', array_merge($git, ['remote', 'add', 'origin', $url]), true, true);
        } elseif ($url !== '') {
            $cur = git_out(['remote', 'get-url', 'origin']);
            if ($cur === null) {
                $exec('Add origin remote', array_merge($git, ['remote', 'add', 'origin', $url]), true, true);
            } elseif ($cur !== $url) {
                $exec('Update origin URL', array_merge($git, ['remote', 'set-url', 'origin', $url]), true, true);
            }
        }
        $before = (string) git_out(['rev-parse', 'HEAD']);

        if ($rollbackTo) {
            if (git_out(['cat-file', '-e', $rollbackTo . '^{commit}']) === null) {
                throw new RuntimeException("Commit $rollbackTo does not exist locally.");
            }
        } else {
            $exec("Fetch origin/$branch", array_merge($git, ['fetch', '--prune', '--tags', '--force', 'origin',
                "+refs/heads/$branch:refs/remotes/origin/$branch"]), true, true);
            $remote = (string) git_out(['rev-parse', "origin/$branch"]);
            $L($remote === $before ? "\nAlready at origin/$branch ($remote) — running post-deploy steps anyway.\n"
                : "\nUpdating " . ($before ? substr($before, 0, 12) : '(none)') . ' → ' . substr($remote, 0, 12) . "\n");
        }

        if (in_array('down', $steps, true)) {
            $exec('Maintenance mode ON', artisan_cmd(down_args()), false);
        }

        if ($rollbackTo) {
            $exec('Reset working tree to ' . substr($rollbackTo, 0, 12), array_merge($git, ['reset', '--hard', $rollbackTo]), true, true);
        } elseif (setting('sync_strategy') === 'ff' && $before !== '') {
            $curBranch = (string) git_out(['rev-parse', '--abbrev-ref', 'HEAD']);
            if ($curBranch !== $branch) {
                $exec("Switch to branch $branch", array_merge($git, ['checkout', '-B', $branch, "origin/$branch"]), true, true);
            } else {
                $exec('Fast-forward merge', array_merge($git, ['merge', '--ff-only', "origin/$branch"]), true, true);
            }
        } else {
            // Force-sync tracked files to the remote; untracked & ignored files (.env, vendor, storage) are untouched.
            $exec("Sync working tree to origin/$branch", array_merge($git, ['checkout', '--force', '-B', $branch, "origin/$branch"]), true, true);
        }

        if (setting('git_clean') === '1') {
            $clean = array_merge($git, ['clean', '-fd', '-e', '/.env']);
            foreach ([DPLY_DATA, DPLY_DIR . '/.htaccess'] as $keep) {
                if (($rel = repo_rel_path($keep)) !== null && $rel !== '') {
                    array_push($clean, '-e', '/' . $rel);
                }
            }
            $exec('Remove untracked files (git clean)', $clean, false, true);
        }
        if (setting('submodules') === '1' && is_file("$root/.gitmodules")) {
            $exec('Update submodules', array_merge($git, ['submodule', 'update', '--init', '--recursive']), true, true);
        }
        $after = (string) git_out(['rev-parse', 'HEAD']);
        $L("\nNow at: " . (string) git_out(['log', '-1', '--format=%h %s (%an, %cr)']) . "\n");

        foreach ($steps as $s) {
            switch ($s) {
                case 'composer':
                    if (!is_file("$root/composer.json")) {
                        $L("\n(no composer.json — skipping composer)\n");
                        break;
                    }
                    $exec('Composer install', composer_cmd(['install', '--no-dev', '--optimize-autoloader', '--prefer-dist',
                        '--no-interaction', '--no-progress', '--no-ansi']));
                    break;
                case 'migrate':
                    $exec('Run migrations', artisan_cmd(['migrate', '--force']));
                    break;
                case 'storage_link':
                    $exec('Storage link', artisan_cmd(['storage:link']), false);
                    break;
                case 'optimize_clear':
                    $exec('Clear all caches', artisan_cmd(['optimize:clear']), false);
                    break;
                case 'config_cache':
                    $exec('Cache config', artisan_cmd(['config:cache']));
                    break;
                case 'route_cache':
                    $exec('Cache routes', artisan_cmd(['route:cache']), false);
                    break;
                case 'view_cache':
                    $exec('Cache views', artisan_cmd(['view:cache']), false);
                    break;
                case 'event_cache':
                    $exec('Cache events', artisan_cmd(['event:cache']), false);
                    break;
                case 'queue_restart':
                    $exec('Restart queue workers', artisan_cmd(['queue:restart']), false);
                    break;
                case 'custom':
                    foreach (lines(setting('custom_commands')) as $line) {
                        $exec('Custom command', ['/bin/sh', '-c', $line]);
                    }
                    break;
                case 'opcache':
                    if (function_exists('opcache_reset') && PHP_SAPI !== 'cli') {
                        $L("\n▶ Reset OPcache\n" . (@opcache_reset() ? "OPcache reset.\n" : "OPcache not active.\n"));
                    }
                    break;
            }
        }
    } catch (Throwable $e) {
        $ok = false;
        $L("\n✖ " . $e->getMessage() . "\n");
    }
    if (in_array('up', $steps, true)) {
        try {
            $exec('Maintenance mode OFF', artisan_cmd(['up']), false);
        } catch (Throwable $e) {
            $L("\n✖ " . $e->getMessage() . "\n");
        }
    }
    if ($after === '') {
        $after = (string) git_out(['rev-parse', 'HEAD']);
    }
    $L("\n" . ($ok ? '✔ Finished successfully.' : '✖ Finished with errors.') . "\n");
    $pdo->prepare('UPDATE deployments SET status = ?, commit_before = ?, commit_after = ?, log = ?, finished_at = ? WHERE id = ?')
        ->execute([$ok ? 'success' : 'failed', $before, $after, substr($log, -2000000), time(), $id]);
    audit('deploy.finish', "#$id " . ($ok ? 'success' : 'failed') . ' ' . substr($before, 0, 12) . ' → ' . substr($after, 0, 12), $actor);
    flock($lock, LOCK_UN);
    fclose($lock);
    return ['ok' => $ok, 'id' => $id, 'msg' => $ok ? 'Deployment succeeded.' : 'Deployment failed.'];
}

// ---- src/50-layout.php -----------------------------------------------

// ============================================================================
//  HTML layout
// ============================================================================

function h(?string $s): string
{
    return htmlspecialchars((string) $s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function fmt_time(?int $t): string
{
    return $t ? date('Y-m-d H:i:s', $t) : '—';
}

function badge(string $text, string $kind = ''): string
{
    return '<span class="badge ' . ($kind ? 'b-' . $kind : '') . '">' . h($text) . '</span>';
}

function layout_head(string $title, bool $nav = true): string
{
    $u = $nav ? current_user() : null;
    $navHtml = '';
    if ($u) {
        $items = [
            'dashboard' => ['Dashboard', null], 'deploy' => ['Deploy', 'deploy'], 'artisan' => ['Artisan', 'artisan'],
            'terminal'  => ['Terminal', 'terminal'], 'env' => ['.env', 'env'], 'keys' => ['SSH keys', 'keys'],
            'users'     => ['Users', 'admin'], 'security' => ['Security', 'admin'], 'settings' => ['Settings', 'admin'],
            'audit'     => ['Audit log', 'admin'], 'profile' => ['Profile', null],
        ];
        $cur = (string) ($_GET['a'] ?? 'dashboard');
        $navHtml = '<nav>';
        foreach ($items as $k => [$label, $perm]) {
            if ($perm === null || can($perm)) {
                $navHtml .= '<a href="?a=' . $k . '"' . ($cur === $k || ($cur === 'deploy_log' && $k === 'deploy') ? ' class="on"' : '') . '>' . h($label) . '</a>';
            }
        }
        $navHtml .= '</nav><form method="post" action="?a=logout" class="row">' . csrf_field()
            . '<span class="mute">' . h($u['username']) . '</span><button class="sm" type="submit">Sign out</button></form>';
    }
    $css = <<<'CSS'
:root{--bg:#0e1217;--panel:#151b23;--line:#253041;--text:#d7dee8;--mute:#8693a5;--acc:#3fb68b;--warn:#e0a84a;--err:#e5616a;--link:#6cb6ff;--mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
header{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;padding:10px 16px;background:var(--panel);border-bottom:1px solid var(--line)}
.brand{font-weight:700;color:var(--acc);letter-spacing:.05em}header nav{display:flex;flex-wrap:wrap;gap:2px;flex:1}
header nav a{color:var(--mute);text-decoration:none;padding:5px 10px;border-radius:6px}header nav a.on,header nav a:hover{color:var(--text);background:#1f2935}
main{max-width:1200px;margin:0 auto;padding:20px 16px}h1{font-size:20px;margin:0 0 14px}
h2{font-size:12px;margin:0 0 12px;color:var(--mute);text-transform:uppercase;letter-spacing:.06em}
.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px;margin-bottom:16px;min-width:0}
.grid{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}.grid>.card{margin-bottom:0}.stack>*+*{margin-top:16px}
.tbl{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--line);vertical-align:top}
th{color:var(--mute);font-weight:600;font-size:12px;white-space:nowrap}td.k{color:var(--mute);width:180px;white-space:nowrap}
input[type=text],input[type=password],input[type=number],select,textarea{width:100%;background:#0a0e13;color:var(--text);border:1px solid var(--line);border-radius:6px;padding:7px 9px;font:inherit}
input:focus,select:focus,textarea:focus{outline:2px solid #2d6a55;border-color:#2d6a55}
textarea{font:13px/1.45 var(--mono);resize:vertical}label{display:block;margin:0 0 12px}label>span{display:block;color:var(--mute);font-size:12px;margin-bottom:3px}
.chk{display:flex;gap:8px;align-items:flex-start;margin:5px 0}.chk input{margin-top:3px}
button,.btn{background:#212d3c;color:var(--text);border:1px solid #2f3e52;border-radius:6px;padding:7px 14px;font:inherit;cursor:pointer;text-decoration:none;display:inline-block;line-height:1.3}
button:hover{border-color:#4a5d77}button.primary{background:var(--acc);border-color:var(--acc);color:#04130d;font-weight:600}
button.danger{background:transparent;border-color:var(--err);color:var(--err)}button.sm{padding:3px 9px;font-size:12px}button:disabled{opacity:.5;cursor:wait}
.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.row form{margin:0}
.flash{padding:10px 14px;border-radius:8px;margin-bottom:14px;border:1px solid}.flash pre{margin:8px 0 0}
.flash.ok{border-color:var(--acc);background:#0f241c}.flash.err{border-color:var(--err);background:#28141a}.flash.warn{border-color:var(--warn);background:#282012}
pre,.log{background:#0a0e13;border:1px solid var(--line);border-radius:8px;padding:12px;overflow:auto;white-space:pre-wrap;word-break:break-word;font:12.5px/1.45 var(--mono);max-height:70vh;margin:0}
code{font-family:var(--mono);background:#0a0e13;padding:1px 5px;border-radius:4px;font-size:12.5px}
.badge{display:inline-block;padding:0 8px;border-radius:99px;font-size:12px;border:1px solid var(--line);white-space:nowrap}
.b-ok{color:var(--acc);border-color:var(--acc)}.b-err{color:var(--err);border-color:var(--err)}.b-warn{color:var(--warn);border-color:var(--warn)}
.mute{color:var(--mute)}a{color:var(--link)}.small{font-size:12px}.login{max-width:380px;margin:10vh auto}
.agrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px}.agrid button{width:100%;text-align:left}
.term{background:#06080b;border:1px solid var(--line);border-radius:8px;font:13px/1.45 var(--mono)}
.term-out{height:60vh;overflow:auto;padding:12px;white-space:pre-wrap;word-break:break-word}
.term-in{display:flex;gap:8px;align-items:center;border-top:1px solid var(--line);padding:8px 12px}.term-in input{border:0;background:transparent;padding:4px;font:inherit;outline:none}
.t-cmd{color:var(--acc)}.t-err{color:var(--err)}.cwd{color:var(--link);white-space:nowrap}
@media (max-width:640px){td.k{width:auto;white-space:normal}main{padding:16px}}
CSS;
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        . '<meta name="robots" content="noindex,nofollow"><title>' . h($title) . ' · DPLY</title><style>' . $css . '</style></head><body>'
        . ($u ? '<header><span class="brand">DPLY</span>' . $navHtml . '</header>' : '') . '<main>';
}

function layout_foot(): string
{
    $js = <<<'JS'
document.addEventListener('submit',function(e){var f=e.target,s=e.submitter,m=(s&&s.getAttribute('data-confirm'))||f.getAttribute('data-confirm');
if(m&&!confirm(m)){e.preventDefault();return;}if(s&&f.getAttribute('data-once')!==null){setTimeout(function(){s.disabled=true;},0);}},true);
JS;
    return '</main><script nonce="' . csp_nonce() . '">' . $js . '</script></body></html>';
}

function flash_html(): string
{
    $out = '';
    foreach ($_SESSION['flash'] ?? [] as [$type, $msg, $pre]) {
        $out .= '<div class="flash ' . h($type) . '">' . h($msg) . ($pre !== null && $pre !== '' ? '<pre>' . h(strip_ansi($pre)) . '</pre>' : '') . '</div>';
    }
    unset($_SESSION['flash']);
    return $out;
}

function render(string $title, string $body): void
{
    header('Content-Type: text/html; charset=utf-8');
    echo layout_head($title), flash_html(), $body, layout_foot();
}

function render_bare(string $title, string $body, bool $withFlash = false): void
{
    header('Content-Type: text/html; charset=utf-8');
    echo layout_head($title, false), ($withFlash ? flash_html() : ''), $body, layout_foot();
}

function stream_begin(string $title): void
{
    session_write_close();
    @ini_set('zlib.output_compression', '0');
    @ini_set('implicit_flush', '1');
    while (ob_get_level() > 0) {
        @ob_end_flush();
    }
    header('Content-Type: text/html; charset=utf-8');
    header('X-Accel-Buffering: no');
    $js = "new MutationObserver(function(){var l=document.getElementById('log');if(l)l.scrollTop=l.scrollHeight;})"
        . ".observe(document.documentElement,{childList:true,subtree:true,characterData:true});";
    echo layout_head($title), '<script nonce="', csp_nonce(), '">', $js, '</script>',
        '<!--', str_repeat(' ', 2048), '--><h1>', h($title), '</h1><pre class="log" id="log">';
    flush();
}

function stream_out(?string $s): void
{
    echo $s === null ? '<!-- -->' : h(strip_ansi($s));
    flush();
}

function stream_end(string $html): void
{
    echo '</pre>', $html, layout_foot();
    flush();
}

function steps_checkboxes(array $selected, string $name = 'steps[]'): string
{
    $o = '';
    foreach (DPLY_STEPS as $k => $label) {
        $o .= '<label class="chk"><input type="checkbox" name="' . h($name) . '" value="' . h($k) . '"'
            . (in_array($k, $selected, true) ? ' checked' : '') . '><span>' . h($label) . '</span></label>';
    }
    return $o;
}

function laravel_version(): string
{
    $f = project_root() . '/vendor/laravel/framework/src/Illuminate/Foundation/Application.php';
    if (is_file($f) && preg_match("/const VERSION = '([^']+)'/", (string) file_get_contents($f), $m)) {
        return $m[1];
    }
    return 'unknown';
}

// ---- src/60-page-dashboard.php ---------------------------------------

// ============================================================================
//  Dashboard
// ============================================================================

function page_dashboard(): void
{
    $root = project_root();
    $isGit = is_dir("$root/.git");
    $head = $isGit ? git_out(['log', '-1', '--format=%h — %s (%an, %cr)']) : null;
    $branch = $isGit ? git_out(['rev-parse', '--abbrev-ref', 'HEAD']) : null;
    $status = $isGit ? git_out(['status', '--porcelain']) : null;
    $changes = $status === null || $status === '' ? 0 : count(explode("\n", $status));
    $down = is_file("$root/storage/framework/down");

    $warn = [];
    if (!is_https()) {
        $warn[] = 'This page is not served over HTTPS — credentials and tokens travel in clear text.';
    }
    if (is_dir($root) && owner_name($root) !== proc_user()) {
        $warn[] = 'PHP runs as "' . proc_user() . '" but the project is owned by "' . owner_name($root) . '". Git/composer may fail on permissions.';
    }
    if (is_file("$root/.env") && (fileperms("$root/.env") & 0004)) {
        $warn[] = '.env is world-readable. Consider: chmod 640 .env';
    }
    if (path_within(DPLY_DATA, DPLY_DIR) && stripos((string) ($_SERVER['SERVER_SOFTWARE'] ?? ''), 'apache') === false) {
        $warn[] = 'Not running on Apache: make sure your web server denies requests to ' . DPLY_DATA . ' (see header of index.php).';
    }
    $warnHtml = '';
    foreach ($warn as $w) {
        $warnHtml .= '<div class="flash warn">' . h($w) . '</div>';
    }

    $rows = [
        'Project root'    => '<code>' . h($root) . '</code>' . (is_dir($root) ? '' : ' ' . badge('missing', 'err')),
        'Laravel'         => h(laravel_version()),
        'PHP (CLI used)'  => '<code>' . h(php_bin()) . '</code>',
        'Runs as'         => h(proc_user()),
        'Git branch'      => $branch ? h($branch) . ($branch !== setting('branch') ? ' ' . badge('deploy branch: ' . setting('branch'), 'warn') : '') : badge('not a git repo', 'warn'),
        'HEAD'            => $head ? h($head) : '—',
        'Working tree'    => $isGit ? ($changes ? badge("$changes local change(s)", 'warn') : badge('clean', 'ok')) : '—',
        'Maintenance'     => $down ? badge('DOWN', 'err') : badge('up', 'ok'),
        'Git auth'        => h(setting('git_auth')),
        'Disk free'       => is_dir($root) ? h(round((float) @disk_free_space($root) / 1073741824, 1) . ' GB') : '—',
    ];
    $info = '';
    foreach ($rows as $k => $v) {
        $info .= '<tr><td class="k">' . h($k) . '</td><td>' . $v . '</td></tr>';
    }
    $deps = db()->query('SELECT * FROM deployments ORDER BY id DESC LIMIT 6')->fetchAll();
    $dHtml = '';
    foreach ($deps as $d) {
        $dHtml .= '<tr><td>#' . (int) $d['id'] . '</td><td>' . deploy_status_badge($d['status']) . '</td><td>' . h($d['actor'])
            . '</td><td>' . h(fmt_time((int) $d['started_at'])) . '</td><td>' . (can('deploy') ? '<a href="?a=deploy_log&id=' . (int) $d['id'] . '">log</a>' : '') . '</td></tr>';
    }
    render('Dashboard', '<h1>Dashboard</h1>' . $warnHtml . '<div class="grid"><div class="card"><h2>Project</h2><div class="tbl"><table>' . $info
        . '</table></div></div><div class="card"><h2>Recent deployments</h2>'
        . ($dHtml ? '<div class="tbl"><table><tr><th>#</th><th>Status</th><th>By</th><th>Started</th><th></th></tr>' . $dHtml . '</table></div>' : '<p class="mute">None yet.</p>')
        . (can('deploy') ? '<p><a class="btn" href="?a=deploy">Go to deploy →</a></p>' : '') . '</div></div>');
}

function deploy_status_badge(string $s): string
{
    return badge($s, $s === 'success' ? 'ok' : ($s === 'failed' ? 'err' : 'warn'));
}

// ---- src/61-page-deploy.php ------------------------------------------

// ============================================================================
//  Deploy
// ============================================================================

function page_deploy(): void
{
    $root = project_root();
    $isGit = is_dir("$root/.git");
    $branch = setting('branch');
    $remote = setting('repo_url') ?: ($isGit ? (string) git_out(['remote', 'get-url', 'origin']) : '');
    $head = $isGit ? git_out(['log', '-1', '--format=%H%n%h — %s%n%an, %cr']) : null;
    $status = $isGit ? (string) git_out(['status', '--porcelain']) : '';
    [$hash, $subject, $meta] = array_pad(explode("\n", (string) $head), 3, '');

    $statusHtml = $status === '' ? badge('clean', 'ok')
        : badge(count(explode("\n", $status)) . ' local change(s)', 'warn')
        . '<pre class="small">' . h(implode("\n", array_slice(explode("\n", $status), 0, 40))) . '</pre>'
        . '<p class="small mute">With the "reset" strategy these tracked changes are overwritten on deploy.</p>';

    $deps = db()->query('SELECT id, actor, kind, branch, status, commit_before, commit_after, started_at, finished_at FROM deployments ORDER BY id DESC LIMIT 30')->fetchAll();
    $hist = '';
    foreach ($deps as $d) {
        $dur = $d['finished_at'] ? ((int) $d['finished_at'] - (int) $d['started_at']) . 's' : '…';
        $rb = '';
        if ($d['status'] !== 'running' && preg_match('/^[0-9a-f]{40}$/', (string) $d['commit_before']) && $d['commit_before'] !== $d['commit_after']) {
            $rb = '<form method="post" action="?a=deploy" data-once data-confirm="Roll back the code to ' . h(substr($d['commit_before'], 0, 12))
                . ' and re-run your default post-deploy steps? Database migrations are NOT reverted.">' . csrf_field()
                . '<input type="hidden" name="op" value="rollback"><input type="hidden" name="id" value="' . (int) $d['id'] . '">'
                . '<button class="sm danger" type="submit">Roll back to before</button></form>';
        }
        $hist .= '<tr><td>#' . (int) $d['id'] . '</td><td>' . h($d['kind']) . '</td><td>' . deploy_status_badge($d['status']) . '</td><td>' . h($d['actor'])
            . '</td><td><code>' . h(substr((string) $d['commit_before'], 0, 8) ?: '—') . '</code> → <code>' . h(substr((string) $d['commit_after'], 0, 8) ?: '—') . '</code></td><td>'
            . h(fmt_time((int) $d['started_at'])) . '</td><td>' . h($dur) . '</td><td class="row"><a href="?a=deploy_log&id=' . (int) $d['id'] . '">log</a>' . $rb . '</td></tr>';
    }

    render('Deploy', '<h1>Deploy</h1><div class="grid">'
        . '<div class="card"><h2>Current state</h2><div class="tbl"><table>'
        . '<tr><td class="k">Repository</td><td>' . ($remote ? '<code>' . h($remote) . '</code>' : badge('not configured', 'warn')) . '</td></tr>'
        . '<tr><td class="k">Deploy branch</td><td><code>' . h($branch) . '</code></td></tr>'
        . '<tr><td class="k">Auth</td><td>' . h(setting('git_auth')) . (setting('git_auth') === 'ssh' ? ' (' . h(setting('ssh_key') ?: 'no key selected') . ')' : '') . '</td></tr>'
        . '<tr><td class="k">Strategy</td><td>' . (setting('sync_strategy') === 'ff' ? 'fast-forward only' : 'force-sync (reset to remote)') . '</td></tr>'
        . '<tr><td class="k">HEAD</td><td>' . ($head ? h($subject) . '<br><span class="mute small">' . h($meta) . ' · <code>' . h(substr($hash, 0, 12)) . '</code></span>' : '—') . '</td></tr>'
        . '<tr><td class="k">Working tree</td><td>' . ($isGit ? $statusHtml : badge('not a git repo yet — first deploy will initialise it in place', 'warn')) . '</td></tr>'
        . '</table></div>'
        . '<form method="post" action="?a=deploy" data-once class="row" style="margin-top:12px">' . csrf_field()
        . '<input type="hidden" name="op" value="check"><button type="submit">Check for updates</button></form></div>'
        . '<div class="card"><h2>Deploy now</h2><form method="post" action="?a=deploy" data-once data-confirm="Deploy origin/' . h($branch) . ' now?">' . csrf_field()
        . '<input type="hidden" name="op" value="deploy"><p class="mute small">1. fetch origin/' . h($branch) . ' → 2. sync files → 3. selected steps:</p>'
        . steps_checkboxes(default_steps()) . '<p><button class="primary" type="submit">Deploy</button></p></form></div></div>'
        . '<div class="card"><h2>History</h2>' . ($hist ? '<div class="tbl"><table><tr><th>#</th><th>Type</th><th>Status</th><th>By</th><th>Commits</th><th>Started</th><th>Took</th><th></th></tr>'
            . $hist . '</table></div>' : '<p class="mute">No deployments yet.</p>') . '</div>');
}

function do_deploy(): void
{
    $op = (string) ($_POST['op'] ?? '');
    $actor = current_user()['username'];
    $back = '<p class="row" style="margin-top:12px"><a class="btn" href="?a=deploy">← Back to deploy</a></p>';

    if ($op === 'check') {
        $root = project_root();
        if (!is_dir("$root/.git")) {
            flash('warn', 'Not a git repository yet. Configure the repository in Settings and run a deploy to initialise it.');
            redirect('?a=deploy');
        }
        $branch = setting('branch');
        stream_begin('Check for updates');
        $genv = proc_env(true);
        if (($url = trim(setting('repo_url'))) !== '' && git_out(['remote', 'get-url', 'origin']) !== $url) {
            stream_out("Note: origin URL differs from settings; it will be updated on next deploy. Fetching configured URL.\n");
            $fetch = [git_bin(), 'fetch', '--prune', $url, "+refs/heads/$branch:refs/remotes/origin/$branch"];
        } else {
            $fetch = [git_bin(), 'fetch', '--prune', 'origin', "+refs/heads/$branch:refs/remotes/origin/$branch"];
        }
        stream_out('$ ' . cmd_display($fetch) . "\n");
        $r = run_proc($fetch, $root, $genv, 300, 'stream_out');
        stream_out("[exit {$r['code']}]\n\n");
        if ($r['code'] === 0) {
            $log = (string) git_out(['log', '--format=%h  %<(16,trunc)%an  %s', "HEAD..origin/$branch"]);
            $behind = $log === '' ? 0 : count(explode("\n", $log));
            $ahead = (string) git_out(['rev-list', '--count', "origin/$branch..HEAD"]);
            stream_out($behind ? "$behind incoming commit(s) on origin/$branch:\n\n$log\n\n" : "Up to date with origin/$branch.\n");
            if ((int) $ahead > 0) {
                stream_out("⚠ Local HEAD has $ahead commit(s) not on origin/$branch (they would be discarded by a force-sync).\n");
            }
            if ($behind) {
                stream_out("\nChanged files:\n" . (string) git_out(['diff', '--stat=120', "HEAD", "origin/$branch"]) . "\n");
                $files = (string) git_out(['diff', '--name-only', 'HEAD', "origin/$branch"]);
                if (preg_match('#^database/migrations/#m', $files)) {
                    stream_out("\n→ New/changed migrations detected — keep the migrate step enabled.\n");
                }
                if (preg_match('#^composer\.(json|lock)$#m', $files)) {
                    stream_out("→ composer.json/lock changed — keep the composer step enabled.\n");
                }
            }
        }
        audit('deploy.check', "origin/$branch exit {$r['code']}");
        stream_end($back);
        return;
    }

    if ($op === 'deploy' || $op === 'rollback') {
        $target = null;
        $steps = $op === 'deploy' ? selected_steps((array) ($_POST['steps'] ?? [])) : default_steps();
        if ($op === 'rollback') {
            $st = db()->prepare('SELECT commit_before FROM deployments WHERE id = ?');
            $st->execute([(int) ($_POST['id'] ?? 0)]);
            $target = (string) $st->fetchColumn();
            if (!preg_match('/^[0-9a-f]{40}$/', $target)) {
                flash('err', 'That deployment has no commit to roll back to.');
                redirect('?a=deploy');
            }
        }
        stream_begin($op === 'deploy' ? 'Deploying' : 'Rolling back');
        $r = deploy_run($actor, $steps, $target, 'stream_out');
        stream_end('<div class="flash ' . ($r['ok'] ? 'ok' : 'err') . '" style="margin-top:12px">' . h($r['msg'])
            . ($r['id'] ? ' <a href="?a=deploy_log&id=' . $r['id'] . '">Permanent log #' . $r['id'] . '</a>' : '') . '</div>' . $back);
        return;
    }
    redirect('?a=deploy');
}

function page_deploy_log(): void
{
    $st = db()->prepare('SELECT * FROM deployments WHERE id = ?');
    $st->execute([(int) ($_GET['id'] ?? 0)]);
    $d = $st->fetch();
    if (!$d) {
        flash('err', 'Deployment not found.');
        redirect('?a=deploy');
    }
    render('Deployment #' . $d['id'], '<h1>' . h(ucfirst($d['kind'])) . ' #' . (int) $d['id'] . ' ' . deploy_status_badge($d['status']) . '</h1>'
        . '<p class="mute">By ' . h($d['actor']) . ' · ' . h(fmt_time((int) $d['started_at'])) . ' → ' . h(fmt_time((int) $d['finished_at']))
        . ' · steps: ' . h((string) $d['steps']) . '</p><pre class="log">' . h((string) $d['log']) . '</pre>'
        . '<p style="margin-top:12px"><a class="btn" href="?a=deploy">← Back</a></p>');
}

