function page_audit(): void
{
    $q = trim((string) ($_GET['q'] ?? ''));
    if ($q !== '') {
        $st = db()->prepare("SELECT * FROM audit WHERE action LIKE ? OR actor LIKE ? OR ip LIKE ? OR detail LIKE ? ORDER BY id DESC LIMIT 500");
        $like = '%' . str_replace(['%', '_'], ['\%', '\_'], $q) . '%';
        $st->execute([$like, $like, $like, $like]);
        $rows = $st->fetchAll();
    } else {
        $rows = db()->query('SELECT * FROM audit ORDER BY id DESC LIMIT 500')->fetchAll();
    }
    $html = '';
    foreach ($rows as $r) {
        $cls = str_starts_with($r['action'], 'auth.fail') || str_starts_with($r['action'], 'security.block') || str_ends_with($r['action'], 'denied') ? 'err'
            : (str_starts_with($r['action'], 'deploy') ? 'ok' : '');
        $html .= '<tr><td class="small">' . h(fmt_time((int) $r['created_at'])) . '</td><td>' . h($r['actor']) . '</td><td><code>' . h($r['ip']) . '</code></td><td>'
            . badge($r['action'], $cls) . '</td><td class="small">' . h($r['detail']) . '</td></tr>';
    }
    render('Audit log', '<h1>Audit log</h1><form method="get" class="row card"><input type="hidden" name="a" value="audit">'
        . '<input type="text" name="q" value="' . h($q) . '" placeholder="Filter by action, user, IP or detail" style="flex:1;min-width:200px"><button type="submit">Filter</button></form>'
        . '<div class="card tbl"><table><tr><th>When</th><th>User</th><th>IP</th><th>Action</th><th>Detail</th></tr>' . $html . '</table></div>');
}

function page_profile(): void
{
    $u = current_user();
    $totp = '';
    if ($u['totp_secret']) {
        $totp = '<p>' . badge('enabled', 'ok') . ' Two-factor authentication is on.</p><form method="post" action="?a=profile" data-confirm="Disable two-factor authentication?">' . csrf_field()
            . '<input type="hidden" name="op" value="totp_disable"><label><span>Current password</span><input type="password" name="password" required autocomplete="current-password"></label>'
            . '<button class="danger" type="submit">Disable 2FA</button></form>';
    } elseif (!empty($_SESSION['totp_pending'])) {
        $sec = $_SESSION['totp_pending'];
        $uri = 'otpauth://totp/' . rawurlencode('DPLY:' . $u['username']) . '?secret=' . $sec . '&issuer=DPLY&algorithm=SHA1&digits=6&period=30';
        $totp = '<p>Add this secret to your authenticator app (Google Authenticator, 1Password, Aegis…), then enter the current code.</p>'
            . '<p>Secret: <code>' . h(trim(chunk_split($sec, 4, ' '))) . '</code></p><p class="small mute break">URI: <code>' . h($uri) . '</code></p>'
            . '<form method="post" action="?a=profile">' . csrf_field() . '<input type="hidden" name="op" value="totp_enable">'
            . '<label><span>6-digit code</span><input type="text" name="code" inputmode="numeric" required autocomplete="one-time-code"></label>'
            . '<button class="primary" type="submit">Enable 2FA</button></form>';
    } else {
        $totp = '<p class="mute">Protect your account with a time-based one-time code.</p><form method="post" action="?a=profile">' . csrf_field()
            . '<input type="hidden" name="op" value="totp_start"><button type="submit">Set up 2FA</button></form>';
    }
    render('Profile', '<h1>Profile — ' . h($u['username']) . '</h1><div class="grid">'
        . '<form method="post" action="?a=profile" class="card">' . csrf_field() . '<h2>Change password</h2><input type="hidden" name="op" value="password">'
        . '<label><span>Current password</span><input type="password" name="current" required autocomplete="current-password"></label>'
        . '<label><span>New password (min 12)</span><input type="password" name="password" required minlength="12" autocomplete="new-password"></label>'
        . '<label><span>Repeat new password</span><input type="password" name="password2" required minlength="12" autocomplete="new-password"></label>'
        . '<button class="primary" type="submit">Change password</button></form>'
        . '<div class="card"><h2>Two-factor authentication</h2>' . $totp . '</div>'
        . '<div class="card"><h2>Your permissions</h2><p>' . implode(' ', array_map(fn($p) => badge($p), $u['perm_list'])) . '</p></div></div>');
}

function do_profile(): void
{
    $u = current_user();
    $op = (string) ($_POST['op'] ?? '');
    $pdo = db();
    switch ($op) {
        case 'password':
            if (!password_verify((string) ($_POST['current'] ?? ''), $u['password_hash'])) {
                register_failure(client_ip(), 'reauth', $u['username']);
                flash('err', 'Current password is wrong.');
            } elseif (($_POST['password'] ?? '') !== ($_POST['password2'] ?? '')) {
                flash('err', 'New passwords do not match.');
            } elseif ($e = pw_policy((string) $_POST['password'], $u['username'])) {
                flash('err', $e);
            } else {
                $pdo->prepare('UPDATE users SET password_hash = ?, session_version = session_version + 1 WHERE id = ?')->execute([hash_pw((string) $_POST['password']), $u['id']]);
                $_SESSION['sv'] = (int) $u['session_version'] + 1;
                audit('profile.password', 'Password changed');
                flash('ok', 'Password changed. Other sessions were signed out.');
            }
            break;
        case 'totp_start':
            $_SESSION['totp_pending'] = b32_encode(random_bytes(20));
            break;
        case 'totp_enable':
            $sec = (string) ($_SESSION['totp_pending'] ?? '');
            $step = $sec !== '' ? totp_verify($sec, preg_replace('/\D/', '', (string) ($_POST['code'] ?? '')), 0) : null;
            if ($step === null) {
                flash('err', 'Code did not match — check the time on your phone and try again.');
                break;
            }
            $pdo->prepare('UPDATE users SET totp_secret = ?, totp_last = ? WHERE id = ?')->execute([enc($sec), $step, $u['id']]);
            unset($_SESSION['totp_pending']);
            audit('profile.2fa_on', '');
            flash('ok', 'Two-factor authentication enabled.');
            break;
        case 'totp_disable':
            if (!password_verify((string) ($_POST['password'] ?? ''), $u['password_hash'])) {
                register_failure(client_ip(), 'reauth', $u['username']);
                flash('err', 'Wrong password.');
                break;
            }
            $pdo->prepare('UPDATE users SET totp_secret = NULL, totp_last = 0 WHERE id = ?')->execute([$u['id']]);
            audit('profile.2fa_off', '');
            flash('ok', 'Two-factor authentication disabled.');
            break;
    }
    redirect('?a=profile');
}

// ---- src/80-cli.php --------------------------------------------------

// ============================================================================
//  CLI
// ============================================================================

function cli_main(array $argv): int
{
    try {
        ensure_storage();
        db();
    } catch (Throwable $e) {
        fwrite(STDERR, 'Storage error: ' . $e->getMessage() . "\n");
        return 1;
    }
    $cmd = $argv[1] ?? 'help';
    $arg = $argv[2] ?? null;
    $opts = [];
    foreach (array_slice($argv, 2) as $a) {
        if (preg_match('/^--([a-z-]+)(?:=(.*))?$/', $a, $m)) {
            $opts[$m[1]] = $m[2] ?? true;
        }
    }
    $code = 0;
    switch ($cmd) {
        case 'setup':
            if (setup_done() && empty($opts['force'])) {
                echo "Already set up. Use http:set, user:add, user:password (or setup --force).\n";
                $code = 1;
                break;
            }
            echo "=== DPLY setup ===\nData directory: " . DPLY_DATA . "\nProject root:   " . project_root() . "\n";
            $root = cli_prompt('Project root [' . project_root() . ']: ');
            if ($root !== '') {
                if (!is_dir($root)) {
                    echo "Directory not found.\n";
                    return 1;
                }
                set_setting('project_root', (string) realpath($root));
            }
            echo "\n-- HTTP Basic auth (outer gate) --\n";
            if (!cli_set_http()) {
                return 1;
            }
            echo "\n-- Administrator account --\n";
            $u = cli_prompt('Admin username: ');
            if (!preg_match('/^[A-Za-z0-9_.@-]{3,64}$/', $u)) {
                echo "Invalid username.\n";
                return 1;
            }
            $p = cli_new_password($u);
            if ($p === null) {
                return 1;
            }
            if ($row = find_user($u)) {
                db()->prepare("UPDATE users SET password_hash = ?, perms = 'admin', active = 1, session_version = session_version + 1 WHERE id = ?")->execute([hash_pw($p), $row['id']]);
            } else {
                db()->prepare("INSERT INTO users (username, password_hash, perms, created_at) VALUES (?, ?, 'admin', ?)")->execute([$u, hash_pw($p), time()]);
            }
            audit('cli.setup', "Admin $u configured", 'cli', 'cli');
            echo "\n✔ Setup complete. Open the console in your browser (HTTPS!).\n";
            break;
        case 'http:set':
            $code = cli_set_http() ? 0 : 1;
            break;
        case 'user:add':
            if (!$arg || !preg_match('/^[A-Za-z0-9_.@-]{3,64}$/', $arg) || find_user($arg)) {
                echo "Usage: user:add <username> [--perms=admin|deploy,artisan,...]  (username must be new)\n";
                $code = 1;
                break;
            }
            $perms = implode(',', array_intersect(array_keys(DPLY_PERMS), explode(',', (string) ($opts['perms'] ?? 'deploy'))));
            $p = cli_new_password($arg);
            if ($p === null) {
                return 1;
            }
            db()->prepare('INSERT INTO users (username, password_hash, perms, created_at) VALUES (?, ?, ?, ?)')->execute([$arg, hash_pw($p), $perms, time()]);
            audit('cli.user_add', "$arg [$perms]", 'cli', 'cli');
            echo "✔ User $arg created with [$perms].\n";
            break;
        case 'user:password':
            $row = $arg ? find_user($arg) : null;
            if (!$row) {
                echo "Usage: user:password <existing-username>\n";
                $code = 1;
                break;
            }
            $p = cli_new_password($row['username']);
            if ($p === null) {
                return 1;
            }
            db()->prepare('UPDATE users SET password_hash = ?, failed_count = 0, locked_until = 0, session_version = session_version + 1 WHERE id = ?')->execute([hash_pw($p), $row['id']]);
            audit('cli.user_password', $row['username'], 'cli', 'cli');
            echo "✔ Password changed.\n";
            break;
        case 'user:unlock':
        case 'user:2fa-reset':
        case 'user:enable':
            $row = $arg ? find_user($arg) : null;
            if (!$row) {
                echo "Usage: $cmd <existing-username>\n";
                $code = 1;
                break;
            }
            $sql = ['user:unlock' => 'UPDATE users SET failed_count = 0, locked_until = 0 WHERE id = ?',
                'user:2fa-reset' => 'UPDATE users SET totp_secret = NULL, totp_last = 0 WHERE id = ?',
                'user:enable' => 'UPDATE users SET active = 1 WHERE id = ?'][$cmd];
            db()->prepare($sql)->execute([$row['id']]);
            audit('cli.' . $cmd, $row['username'], 'cli', 'cli');
            echo "✔ Done.\n";
            break;
        case 'user:list':
            foreach (db()->query('SELECT username, perms, active, locked_until, totp_secret FROM users ORDER BY username') as $r) {
                printf("%-24s %-40s %s%s%s\n", $r['username'], $r['perms'], $r['active'] ? 'active' : 'disabled',
                    (int) $r['locked_until'] > time() ? ' LOCKED' : '', $r['totp_secret'] ? ' 2FA' : '');
            }
            break;
        case 'unblock':
            if ($arg === '--all') {
                db()->exec('DELETE FROM blocks; DELETE FROM attempts;');
            } elseif ($arg && filter_var($arg, FILTER_VALIDATE_IP)) {
                db()->prepare('DELETE FROM blocks WHERE ip = ?')->execute([$arg]);
                db()->prepare('DELETE FROM attempts WHERE ip = ?')->execute([$arg]);
            } else {
                echo "Usage: unblock <ip>|--all\n";
                $code = 1;
                break;
            }
            audit('cli.unblock', (string) $arg, 'cli', 'cli');
            echo "✔ Unblocked.\n";
            break;
        case 'blocks':
            foreach (db()->query('SELECT * FROM blocks WHERE until > ' . time()) as $b) {
                printf("%-40s until %s  strikes %d  %s\n", $b['ip'], date('Y-m-d H:i:s', (int) $b['until']), $b['strikes'], $b['reason']);
            }
            break;
        case 'allowlist:clear':
            set_setting('ip_allowlist', '');
            audit('cli.allowlist_clear', '', 'cli', 'cli');
            echo "✔ IP allow-list cleared.\n";
            break;
        case 'deploy':
            $steps = isset($opts['steps']) && is_string($opts['steps']) ? selected_steps(explode(',', $opts['steps'])) : default_steps();
            $r = deploy_run('cli', $steps, null, function (?string $s) {
                if ($s !== null) {
                    echo $s;
                }
            });
            echo "\n" . $r['msg'] . ($r['id'] ? " (#{$r['id']})" : '') . "\n";
            $code = $r['ok'] ? 0 : 1;
            break;
        default:
            echo <<<TXT
DPLY {$GLOBALS['argv'][0]} — commands:
  setup [--force]          Initial setup: HTTP auth credentials + admin account
  http:set                 Change HTTP Basic auth username/password
  user:add <name> [--perms=deploy,artisan,terminal,terminal_full,env,keys,admin]
  user:password <name>     Set a user's password (also unlocks)
  user:unlock <name>       Clear a user's lockout
  user:enable <name>       Re-enable a disabled user
  user:2fa-reset <name>    Remove a user's two-factor secret
  user:list                List users
  blocks                   List currently blocked IPs
  unblock <ip>|--all       Remove IP blocks
  allowlist:clear          Remove the IP allow-list (if you locked yourself out)
  deploy [--steps=a,b,c]   Run a deployment from the command line

Run as the same user PHP-FPM/Apache uses, e.g.: sudo -u www-data php index.php setup

TXT;
    }
    cli_fix_owner();
    return $code;
}

function cli_prompt(string $q, bool $hidden = false): string
{
    fwrite(STDOUT, $q);
    $tty = function_exists('posix_isatty') ? @posix_isatty(STDIN) : (function_exists('stream_isatty') && @stream_isatty(STDIN));
    if ($hidden && $tty) {
        @shell_exec('stty -echo 2>/dev/null');
        $v = fgets(STDIN);
        @shell_exec('stty echo 2>/dev/null');
        fwrite(STDOUT, "\n");
    } else {
        $v = fgets(STDIN);
    }
    return $v === false ? '' : rtrim($v, "\r\n");
}

function cli_new_password(string $username): ?string
{
    $p = cli_prompt('Password (min 12 chars): ', true);
    if ($e = pw_policy($p, $username)) {
        echo $e . "\n";
        return null;
    }
    if (cli_prompt('Repeat password: ', true) !== $p) {
        echo "Passwords do not match.\n";
        return null;
    }
    return $p;
}

function cli_set_http(): bool
{
    $u = cli_prompt('HTTP auth username: ');
    if ($u === '' || strlen($u) > 64 || str_contains($u, ':')) {
        echo "Invalid username (1-64 chars, no ':').\n";
        return false;
    }
    $p = cli_new_password($u);
    if ($p === null) {
        return false;
    }
    set_setting('http_user', $u);
    set_setting('http_pass_hash', hash_pw($p));
    audit('cli.http_auth', "HTTP auth set (user $u)", 'cli', 'cli');
    echo "✔ HTTP auth credentials saved.\n";
    return true;
}

/** If run as root, hand the data directory to the owner of this script so the web server can use it. */
function cli_fix_owner(): void
{
    if (!function_exists('posix_geteuid') || posix_geteuid() !== 0) {
        return;
    }
    $uid = (int) fileowner(__FILE__);
    $gid = (int) filegroup(__FILE__);
    if ($uid === 0) {
        fwrite(STDERR, "Warning: running as root and index.php is owned by root — make sure " . DPLY_DATA . " is owned by the web server user.\n");
        return;
    }
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator(DPLY_DATA, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);
    @chown(DPLY_DATA, $uid);
    @chgrp(DPLY_DATA, $gid);
    foreach ($it as $f) {
        @chown((string) $f, $uid);
        @chgrp((string) $f, $gid);
    }
    fwrite(STDERR, "Note: ran as root — data directory ownership handed to uid $uid (owner of index.php).\n");
}

